TOOLS = ('stats search sections context ask read related toc map topic_tree sources document shelves elsewhere grab url '
         'web arxiv youtube github gh_file add_file add_dir add_tree note connect forget apis harvest watch watches '
         'poll schedule jobs retry_job unwatch index_code code_search symbol where_to_add grep federate categorize '
         'categorize_all doctypes of_type ner reshelf extract extract_all ask_doc '
         'pii mark_pii mark_not_pii mark_noisy mark_noisy_many marks level findings send_check '
         'add_image add_images images tag_image label_images '
         'suggest_noisy accept_noisy learn fit_noise use_noise').split()

mcp = MCPServer('vishalakshi', instructions=(
    'A personal research vault: web pages, papers, transcripts, files, code and notes in one '
    'searchable corpus. `context` is the main tool: it returns whole sections plus what they '
    'connect to, which is what you want before answering a question. `search` locates things, '
    '`read` pulls one section in full, `related` answers "what else reads like this". `grab` '
    'files anything you point it at; `note` writes your own conclusions back so they are searched '
    'alongside the sources. `add_tree` points at a directory and splits it: documents into the '
    'vault, source files into kosha. When kosha has indexed '
    'the repo, `context` and `ask` add code sections to what they retrieve on their own, so a '
    'question about the user\'s own system is answered from the source rather than from prose about '
    'it.\n\n'
    'For one document rather than the corpus: `document` returns the whole of it, `categorize` says '
    'what kind of thing it is (invoice, catalogue, contract, paper, …), `extract` pulls its fields '
    'out against a schema (a name like `invoice`, or a spec like `vendor:str, total:float` you '
    'make up on the spot), and `ask_doc` answers a question about that document with the rest of '
    'the vault as context, as prose or as a shape you name. `extract_all` does it across every '
    'document of one type, which is how a folder of invoices becomes a table.\n\n'
    'Judgement loop: `suggest_noisy` ranks junk and `mark_noisy` / `accept_noisy` exclude it from '
    'retrieval. `pii` says whether a document is private; `mark_pii` and `mark_not_pii` overrule '
    'the detector.'))

#: fields that name a row or say how it was judged. A client needs them to ask again. They are never masked
KEEP = ('doc_id', 'node_id', 'id', 'store', 'ref', 'level', 'how', 'policy', 'kind')

def client_view(o, v, ner:bool=False):
    "Return what an MCP client receives for a result. Each string under a Local only document is withheld. Every other string goes through `redact`, except in a cleared document, which is returned as stored. The result has no `prompt`."
    cleared, _, local, fl = _level_sets(v)
    loc = held({'local': 1})
    def walk(x, k=None):
        if isinstance(x, str): return loc if k and (fl == 'local' or k in local) else x if k in cleared else redact(x, ner=ner)
        if isinstance(x, list): return [walk(y, k) for y in x]
        if not isinstance(x, dict): return x
        k = _row_key(x, v.name) or k
        return {f: y if f in KEEP else walk(y, k) for f, y in x.items() if f != 'prompt'}
    # a local model read a Local only section whole; whatever it wrote can repeat it
    if isinstance(o, dict) and any(r.get('level') == 'local' and r.get('how') != 'withheld' for r in (o.get('send') or {}).get('rows') or ()):
        o = dict(o, **{f: loc for f in ('answer', 'thinking', 'fields') if o.get(f)})
    return walk(o)

def as_tool(name:str):
    "Register one `Vault` method as an MCP tool that returns JSON through `client_view`. The tool fixes `by` to `'agent'` and hides it. The default of `pii` is `redact`."
    f = cmd(name)
    ps = f.__signature__.parameters
    by = dict(by='agent') if 'by' in ps else {}
    def g(**kw):
        if 'pii' in ps:
            kw['pii'] = kw.get('pii') or 'redact'
            if kw['pii'] == 'off': _person('agent', 'turn the pii gate off')
        return client_view(json.loads(json.dumps(f(**kw, **by), default=jsonable)), vault(), ner=kw.get('pii_ner', False))
    g = wraps(f)(g)
    g.__signature__ = f.__signature__.replace(parameters=[v.replace(default='redact') if k == 'pii' else v for k, v in ps.items() if k != 'by'])
    g.__delwrap__, g.__annotations__ = f.__delwrap__, {k: v for k, v in f.__annotations__.items() if k != 'by'}
    return mcp.tool(name=name)(g)

for _t in TOOLS: as_tool(_t)

def main():
    "Run the `vishalakshi-mcp` server, over standard input and output, or Streamable HTTP with `--http`."
    mcp.run(transport='streamable-http' if '--http' in sys.argv[1:] else 'stdio')
